package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1apx2ktj0tc7gqzaqtgl9xluflnqehgpqla0anv"), 5),
			valv3.NewValoperChange(address("g15g0la8fyn4mvulrw39vmngs3z9vzhefkyyef9y"), 5),
		},
		"Add 2 validator(s) to the valset",
		"Batch-add 2 operator(s) to the active valset with voting power 5.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

