// Package nftmarket is a non-custodial GNOT marketplace for collections
// minted through gno.land/r/hazen/nft.
//
// Non-custodial: listing a token never moves it into this realm. Instead
// the seller approves this realm's address as an operator on
// gno.land/r/hazen/nft (Approve or SetApprovalForAll), and List just
// records the intent to sell. At Buy time this realm cross-calls
// nft.TransferFrom on the seller's behalf — which only succeeds while the
// approval still stands — so a seller can invalidate every open listing
// at once just by transferring the token or revoking the approval.
package nftmarket

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// Listing is one active or historical sale offer.
type Listing struct {
	id           string
	collectionID string
	tokenID      string
	seller       address
	priceUgnot   int64
	active       bool
	createdAt    int64
}

// ListingInfo is the exported, read-only view of a Listing.
type ListingInfo struct {
	ID           string
	CollectionID string
	TokenID      string
	Seller       address
	PriceUgnot   int64
	Active       bool
	CreatedAt    int64
}

var (
	listings = avl.NewTree() // listingID -> *Listing
	byToken  = avl.NewTree() // "collectionId:tokenId" -> listingID (only one active listing per token)
	nextID   int64
)

// List offers a token for sale at priceUgnot (denominated in ugnot, i.e.
// 1 GNOT = 1_000_000). The caller must already own the token and must have
// approved this realm's address on gno.land/r/hazen/nft beforehand
// (nft.Approve or nft.SetApprovalForAll), otherwise Buy will fail later.
func List(cur realm, collectionID, tokenID string, priceUgnot int64) string {
	// List/Cancel/Buy are always meant to be called directly by an EOA,
	// so caller comes from unsafe.OriginCaller() (the tx's real signer)
	// rather than cur.Previous().Address(). Only nft.TransferFrom (called
	// from Buy below) actually needs the direct-caller distinction, to
	// let this realm act as the seller's approved operator.
	caller := unsafe.OriginCaller()
	if priceUgnot <= 0 {
		panic("price must be positive")
	}

	owner, err := nft.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can list it")
	}

	marketAddr := cur.Address()
	approved, _ := nft.GetApproved(collectionID, tokenID)
	if approved != marketAddr && !nft.IsApprovedForAll(collectionID, owner, marketAddr) {
		panic("marketplace is not approved to transfer this token yet; call nft.Approve or nft.SetApprovalForAll first")
	}

	key := collectionID + ":" + tokenID
	if listingID, ok := byToken.Get(key).(string); ok {
		if l, ok2 := listings.Get(listingID).(*Listing); ok2 && l.active {
			panic("token is already listed (listing #" + listingID + ")")
		}
	}

	nextID++
	id := strconv.FormatInt(nextID, 10)
	l := &Listing{
		id:           id,
		collectionID: collectionID,
		tokenID:      tokenID,
		seller:       caller,
		priceUgnot:   priceUgnot,
		active:       true,
		createdAt:    runtime.ChainHeight(),
	}
	listings.Set(id, l)
	byToken.Set(key, id)

	chain.Emit(
		"NFTListed",
		"listingId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", caller.String(),
		"price", strconv.FormatInt(priceUgnot, 10),
	)

	return id
}

// Cancel withdraws an active listing. Only the original seller may cancel.
func Cancel(cur realm, listingID string) {
	caller := unsafe.OriginCaller()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can cancel this listing")
	}

	l.active = false
	byToken.Remove(l.collectionID + ":" + l.tokenID)

	chain.Emit("NFTListingCancelled", "listingId", listingID)
}

// Buy purchases an active listing. The transaction must send at least the
// listing's priceUgnot in ugnot (--send "<price>ugnot" on maketx call); any
// excess is refunded to the buyer. Royalties declared on the token (via
// its collection's royaltyPct, set automatically at Mint) are paid to the
// collection creator before the remainder goes to the seller.
func Buy(cur realm, listingID string) {
	caller := unsafe.OriginCaller()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller == caller {
		panic("cannot buy your own listing")
	}

	sent := unsafe.OriginSend()
	sentAmt := sent.AmountOf("ugnot")
	if sentAmt < l.priceUgnot {
		panic("insufficient payment: sent " + strconv.FormatInt(sentAmt, 10) +
			"ugnot, need " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot")
	}

	marketAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	sellerAmt := l.priceUgnot
	if royaltyAddr, royaltyAmt, err := nft.RoyaltyInfo(l.collectionID, l.tokenID, l.priceUgnot); err == nil {
		if royaltyAmt > 0 && royaltyAmt < l.priceUgnot && royaltyAddr != l.seller {
			sellerAmt = l.priceUgnot - royaltyAmt
			bk.SendCoins(marketAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
		}
	}
	bk.SendCoins(marketAddr, l.seller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))

	if sentAmt > l.priceUgnot {
		bk.SendCoins(marketAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", sentAmt-l.priceUgnot)))
	}

	// Cross into gno.land/r/hazen/nft to move ownership. This only
	// succeeds if the seller's approval (granted directly on the nft
	// realm) is still standing; a revoked/expired approval reverts this
	// entire transaction, including the coin transfers above.
	nft.TransferFrom(cross(cur), l.collectionID, l.tokenID, l.seller, caller)

	l.active = false
	byToken.Remove(l.collectionID + ":" + l.tokenID)

	chain.Emit(
		"NFTSold",
		"listingId", listingID,
		"collection", l.collectionID,
		"tokenId", l.tokenID,
		"seller", l.seller.String(),
		"buyer", caller.String(),
		"price", strconv.FormatInt(l.priceUgnot, 10),
	)
}

// Read-only views.

// GetListing returns one listing by ID.
func GetListing(listingID string) ListingInfo {
	return toInfo(mustGetListing(listingID))
}

// ListActive returns up to `limit` active listings starting at `offset`
// (offset/limit apply to the full listing set, active or not, so callers
// should over-fetch slightly if they need an exact page of active-only
// results).
func ListActive(offset, limit int64) []ListingInfo {
	out := make([]ListingInfo, 0, limit)
	listings.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		l := value.(*Listing)
		if l.active {
			out = append(out, toInfo(l))
		}
		return false
	})
	return out
}

// ListingCount returns the total number of listings ever created
// (active + inactive).
func ListingCount() int64 {
	return nextID
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		l, ok := listings.Get(path).(*Listing)
		if !ok {
			return "# 404\n\nlisting not found: " + path
		}
		return renderListing(l)
	}

	out := "# Hazen NFT Marketplace\n\n"
	hasActive := false
	listings.Iterate("", "", func(key string, value any) bool {
		l := value.(*Listing)
		if !l.active {
			return false
		}
		hasActive = true
		out += renderListing(l) + "\n"
		return false
	})
	if !hasActive {
		out += "No active listings.\n"
	}
	return out
}

func renderListing(l *Listing) string {
	status := "active"
	if !l.active {
		status = "sold/cancelled"
	}
	return "- #" + l.id + " " + l.collectionID + ":" + l.tokenID +
		" — " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot — seller " + l.seller.String() +
		" (" + status + ")"
}

func toInfo(l *Listing) ListingInfo {
	return ListingInfo{
		ID:           l.id,
		CollectionID: l.collectionID,
		TokenID:      l.tokenID,
		Seller:       l.seller,
		PriceUgnot:   l.priceUgnot,
		Active:       l.active,
		CreatedAt:    l.createdAt,
	}
}

func mustGetListing(id string) *Listing {
	v := listings.Get(id)
	if v == nil {
		panic("listing not found: " + id)
	}
	return v.(*Listing)
}

package nftmarket

import (
	"chain"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// NOTE: testing.SetOriginCaller overrides unsafe.OriginCaller() for the
// remainder of the *calling function's own stack frame* — so every call
// below is inlined directly in the test/t.Run closure body, right before
// the action(s) it's meant to affect (see nft_test.gno for more detail on
// why factoring this into a shared helper function breaks it).

func TestListAndBuy(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice")
	bob := testutils.TestAddress("mkt-bob")

	var collID, tid, listingID string
	marketAddr := cur.Address()

	t.Run("alice creates, mints, approves and lists", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID = nft.CreateCollection(cross(cur), "Market Test", "MKT", "", "", 5, 10, true)
		tid = nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)
		listingID = List(cross(cur), collID, tid, 1_000_000) // 1 GNOT

		info := GetListing(listingID)
		uassert.True(t, info.Active, "listing should be active")
		uassert.Equal(t, int64(1_000_000), info.PriceUgnot)
	})

	t.Run("bob buys it", func(t *testing.T) {
		testing.SetOriginCaller(bob)
		// On real chain, a --send amount is credited to the CALLED
		// REALM's account before the function runs; gno test doesn't do
		// this automatically, so IssueCoins simulates that deposit onto
		// the marketplace realm itself (not bob) to match what Buy's
		// banker.SendCoins calls actually need.
		testing.IssueCoins(marketAddr, chain.NewCoins(chain.NewCoin("ugnot", 1_000_000)))
		testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1_000_000)))

		Buy(cross(cur), listingID)

		owner, err := nft.OwnerOf(collID, tid)
		uassert.NoError(t, err, "OwnerOf should not error")
		uassert.Equal(t, bob, owner)

		sold := GetListing(listingID)
		uassert.False(t, sold.Active, "listing should be inactive after sale")
	})
}

func TestCancelListing(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice2")
	marketAddr := cur.Address()

	var listingID string
	t.Run("alice lists then cancels", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "Cancel Test", "CNCL", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)

		listingID = List(cross(cur), collID, tid, 500_000)
		Cancel(cross(cur), listingID)
	})

	t.Run("listing is inactive", func(t *testing.T) {
		info := GetListing(listingID)
		uassert.False(t, info.Active, "listing should be inactive after cancel")
	})
}

func TestListRequiresApproval(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice3")

	t.Run("listing without approval aborts", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "NoApprove", "NOAP", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")

		uassert.AbortsWithMessage(t, cur,
			"marketplace is not approved to transfer this token yet; call nft.Approve or nft.SetApprovalForAll first",
			func() {
				List(cross(cur), collID, tid, 1)
			},
		)
	})
}

func TestCannotBuyOwnListing(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mkt-alice4")
	marketAddr := cur.Address()

	var listingID string
	t.Run("alice lists", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID := nft.CreateCollection(cross(cur), "SelfBuy", "SELF", "", "", 5, 0, true)
		tid := nft.Mint(cross(cur), collID, "")
		nft.Approve(cross(cur), collID, tid, marketAddr)
		listingID = List(cross(cur), collID, tid, 100)
	})

	t.Run("alice cannot buy it back", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		testing.IssueCoins(alice, chain.NewCoins(chain.NewCoin("ugnot", 1_000)))
		testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 100)))

		uassert.AbortsWithMessage(t, cur, "cannot buy your own listing", func() {
			Buy(cross(cur), listingID)
		})
	})
}

// Package nftoffers is a non-custodial offer/bid system for tokens minted
// through gno.land/r/hazen/nft. It is a separate realm from nftmarket
// (rather than an addition to it) because gno.land packages are immutable
// once deployed — nftmarket was already live with real listings, so any
// new feature has to ship as its own realm instead of an in-place upgrade.
//
// Unlike nftmarket's List/Buy (seller sets a fixed price, first buyer
// wins), offers let any interested buyer propose a price on ANY token —
// listed on nftmarket or not — by escrowing GNOT in this realm up front.
// The token owner can then Accept the best/any offer at their discretion,
// or the buyer can Cancel to get a full refund while it's still pending.
//
// Escrow model: MakeOffer's --send amount is credited to this realm's own
// balance (that's how a `/vm.m_call` with a send value works), and stays
// there until AcceptOffer pays it out (to the seller, minus royalty) or
// CancelOffer refunds it to the original buyer. The NFT itself is never
// escrowed — same non-custodial approval pattern as nftmarket: the owner
// must Approve/SetApprovalForAll this realm's address on nft.gno before
// AcceptOffer's cross-realm TransferFrom can succeed.
package nftoffers

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// Offer is one pending or historical bid on a token.
type Offer struct {
	id           string
	collectionID string
	tokenID      string
	buyer        address
	amountUgnot  int64
	active       bool
	createdAt    int64
}

// OfferInfo is the exported, read-only view of an Offer.
type OfferInfo struct {
	ID           string
	CollectionID string
	TokenID      string
	Buyer        address
	AmountUgnot  int64
	Active       bool
	CreatedAt    int64
}

var (
	offers = avl.NewTree() // offerID -> *Offer
	nextID int64
)

// MakeOffer escrows the transaction's --send amount (in ugnot) as an offer
// on collectionID:tokenID. Any number of offers can be pending on the same
// token at once (from the same or different buyers); the owner chooses
// which, if any, to Accept. The token does not need to be owned by anyone
// in particular other than "not the caller" — offers work whether or not
// the token is also listed on nftmarket.
func MakeOffer(cur realm, collectionID, tokenID string) string {
	caller := unsafe.OriginCaller()

	sent := unsafe.OriginSend()
	amt := sent.AmountOf("ugnot")
	if amt <= 0 {
		panic("offer must send a positive ugnot amount")
	}

	owner, err := nft.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner == caller {
		panic("cannot make an offer on your own token")
	}

	nextID++
	id := strconv.FormatInt(nextID, 10)
	o := &Offer{
		id:           id,
		collectionID: collectionID,
		tokenID:      tokenID,
		buyer:        caller,
		amountUgnot:  amt,
		active:       true,
		createdAt:    runtime.ChainHeight(),
	}
	offers.Set(id, o)

	chain.Emit(
		"OfferMade",
		"offerId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"buyer", caller.String(),
		"amount", strconv.FormatInt(amt, 10),
	)

	return id
}

// CancelOffer withdraws a pending offer and refunds the escrowed amount to
// the buyer. Only the buyer who made the offer may cancel it.
func CancelOffer(cur realm, offerID string) {
	caller := unsafe.OriginCaller()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if o.buyer != caller {
		panic("only the offer's buyer can cancel it")
	}

	o.active = false

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), o.buyer, chain.NewCoins(chain.NewCoin("ugnot", o.amountUgnot)))

	chain.Emit("OfferCancelled", "offerId", offerID)
}

// AcceptOffer sells the token to the offer's buyer at the offer's escrowed
// price. Only the token's current owner may accept, and the owner must
// have already approved this realm's address on nft.gno (Approve or
// SetApprovalForAll), the same non-custodial pattern nftmarket uses.
// Royalties are paid out automatically, same as nftmarket.Buy.
func AcceptOffer(cur realm, offerID string) {
	caller := unsafe.OriginCaller()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}

	owner, err := nft.OwnerOf(o.collectionID, o.tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the current token owner can accept this offer")
	}
	if o.buyer == caller {
		panic("cannot accept your own offer")
	}

	realmAddr := cur.Address()
	approved, _ := nft.GetApproved(o.collectionID, o.tokenID)
	if approved != realmAddr && !nft.IsApprovedForAll(o.collectionID, owner, realmAddr) {
		panic("nftoffers is not approved to transfer this token yet; call nft.Approve or nft.SetApprovalForAll first")
	}

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	sellerAmt := o.amountUgnot
	if royaltyAddr, royaltyAmt, err := nft.RoyaltyInfo(o.collectionID, o.tokenID, o.amountUgnot); err == nil {
		if royaltyAmt > 0 && royaltyAmt < o.amountUgnot && royaltyAddr != owner {
			sellerAmt = o.amountUgnot - royaltyAmt
			bk.SendCoins(realmAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
		}
	}
	bk.SendCoins(realmAddr, owner, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))

	// Cross into nft.gno to move ownership, same approval-dependent
	// pattern as nftmarket.Buy: this reverts the whole tx (including the
	// coin transfers above) if the owner's approval no longer stands.
	nft.TransferFrom(cross(cur), o.collectionID, o.tokenID, owner, o.buyer)

	o.active = false

	chain.Emit(
		"OfferAccepted",
		"offerId", offerID,
		"collection", o.collectionID,
		"tokenId", o.tokenID,
		"seller", owner.String(),
		"buyer", o.buyer.String(),
		"amount", strconv.FormatInt(o.amountUgnot, 10),
	)
}

// Read-only views.

// GetOffer returns one offer by ID.
func GetOffer(offerID string) OfferInfo {
	return toInfo(mustGetOffer(offerID))
}

// OffersForToken returns every active offer on one token, most recent
// first. Fine to iterate the full offer set at this project's scale;
// revisit with a secondary "collectionId:tokenId -> []offerId" index if
// the offer volume ever makes this too slow.
func OffersForToken(collectionID, tokenID string) []OfferInfo {
	var out []OfferInfo
	offers.Iterate("", "", func(key string, value any) bool {
		o := value.(*Offer)
		if o.active && o.collectionID == collectionID && o.tokenID == tokenID {
			out = append(out, toInfo(o))
		}
		return false
	})
	return out
}

// OffersByBuyer returns every active offer the given address has made,
// so a buyer can see/cancel their own pending offers (the "My Offers"
// counterpart to nftmarket's "My Listings").
func OffersByBuyer(buyer address) []OfferInfo {
	var out []OfferInfo
	offers.Iterate("", "", func(key string, value any) bool {
		o := value.(*Offer)
		if o.active && o.buyer == buyer {
			out = append(out, toInfo(o))
		}
		return false
	})
	return out
}

// OfferCount returns the total number of offers ever created (active +
// inactive).
func OfferCount() int64 {
	return nextID
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		o, ok := offers.Get(path).(*Offer)
		if !ok {
			return "# 404\n\noffer not found: " + path
		}
		return renderOffer(o)
	}

	out := "# Hazen NFT Offers\n\n"
	hasActive := false
	offers.Iterate("", "", func(key string, value any) bool {
		o := value.(*Offer)
		if !o.active {
			return false
		}
		hasActive = true
		out += renderOffer(o) + "\n"
		return false
	})
	if !hasActive {
		out += "No active offers.\n"
	}
	return out
}

func renderOffer(o *Offer) string {
	status := "active"
	if !o.active {
		status = "resolved"
	}
	return "- #" + o.id + " " + o.collectionID + ":" + o.tokenID +
		" — " + strconv.FormatInt(o.amountUgnot, 10) + "ugnot — buyer " + o.buyer.String() +
		" (" + status + ")"
}

func toInfo(o *Offer) OfferInfo {
	return OfferInfo{
		ID:           o.id,
		CollectionID: o.collectionID,
		TokenID:      o.tokenID,
		Buyer:        o.buyer,
		AmountUgnot:  o.amountUgnot,
		Active:       o.active,
		CreatedAt:    o.createdAt,
	}
}

func mustGetOffer(id string) *Offer {
	v := offers.Get(id)
	if v == nil {
		panic("offer not found: " + id)
	}
	return v.(*Offer)
}

