// Package streak is an on-chain check-in streak tracker: call CheckIn once per
// "day" to keep a streak alive, miss one and it resets to 1.
//
// There is no wall clock on-chain, so a "day" here is a fixed window of
// BlocksPerDay blocks: day = ChainHeight() / BlocksPerDay. That makes every
// streak decision a pure function of block height — deterministic, replayable,
// and impossible to game by waiting for a favourable timestamp.
//
// State is per-caller and append-only in spirit: an address's best streak is
// never lowered, so breaking a run costs the current streak but not the record.
//
// This is a stateful app with nothing reusable to extract, so it ships as a
// lone realm rather than a p/ library + demo pair.
package streak

import (
	"sort"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// BlocksPerDay is the length of a check-in window, in blocks. Chosen so a
// window is a meaningful stretch of chain activity while keeping tests and
// demos quick to reason about.
const BlocksPerDay = 1000

// maxLeaderboard caps how many entries Render lists.
const maxLeaderboard = 10

// record is one address's streak state.
type record struct {
	current int   // consecutive days up to lastDay
	best    int   // highest current ever reached; never lowered
	lastDay int64 // day index of the most recent check-in
	totalIn int   // total check-ins ever
}

// users maps address string -> *record.
var users = avl.NewTree()

// today returns the current day index: block height divided into fixed windows.
func today() int64 { return runtime.ChainHeight() / BlocksPerDay }

// CheckIn records a check-in for the caller and returns the resulting streak.
//
// Checking in twice in the same window is rejected — the streak only moves when
// the window does. A gap of exactly one window continues the streak; any larger
// gap restarts it at 1.
func CheckIn(cur realm) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can check in")
	}
	addr := prev.Address()
	day := today()

	r := get(addr)
	if r == nil {
		r = &record{}
		users.Set(addr.String(), r)
	} else {
		switch {
		case r.totalIn > 0 && r.lastDay == day:
			panic("already checked in for day " + strconv.FormatInt(day, 10))
		case r.totalIn > 0 && r.lastDay == day-1:
			// consecutive window: the streak continues below
		default:
			// missed at least one window: the run is broken
			r.current = 0
		}
	}

	r.current++
	r.lastDay = day
	r.totalIn++
	if r.current > r.best {
		r.best = r.current
	}

	chain.Emit("CheckIn",
		"addr", addr.String(),
		"day", strconv.FormatInt(day, 10),
		"streak", strconv.Itoa(r.current),
	)
	return r.current
}

// get returns the caller's record, or nil.
//
// avl/v0's Get returns a single `any` (not the value, ok pair Go maps use), so
// a missing key surfaces as a nil interface rather than a second return value.
func get(addr address) *record {
	v := users.Get(addr.String())
	if v == nil {
		return nil
	}
	return v.(*record)
}

// Current returns addr's live streak — 0 once a window has been missed, even
// though the stored value only updates on the next check-in.
func Current(addr address) int {
	r := get(addr)
	if r == nil {
		return 0
	}
	day := today()
	if r.lastDay != day && r.lastDay != day-1 {
		return 0
	}
	return r.current
}

// Best returns addr's record streak, which is never lowered.
func Best(addr address) int {
	r := get(addr)
	if r == nil {
		return 0
	}
	return r.best
}

// Day returns the current day index.
func Day() int64 { return today() }

// entry is a flattened record for rendering.
type entry struct {
	addr    string
	current int
	best    int
	total   int
}

// byBest ranks entries by best streak descending, then by address so equal
// scores always come out in the same order (Render must be deterministic).
type byBest []entry

func (e byBest) Len() int      { return len(e) }
func (e byBest) Swap(i, j int) { e[i], e[j] = e[j], e[i] }
func (e byBest) Less(i, j int) bool {
	if e[i].best != e[j].best {
		return e[i].best > e[j].best
	}
	return e[i].addr < e[j].addr
}

// Render renders the streak board for gnoweb.
//
//	Render("")          / Render("/") -> leaderboard by best streak
//	Render("/<address>")             -> that address's standing
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Check-in Streaks\n\n")
	b.WriteString("A \"day\" is ")
	b.WriteString(strconv.Itoa(BlocksPerDay))
	b.WriteString(" blocks — there is no clock on-chain, so streaks are decided by block height alone.\n\n")
	b.WriteString("Current day: **")
	b.WriteString(strconv.FormatInt(today(), 10))
	b.WriteString("**\n\n")

	if q := parseArg(path); q != "" {
		return b.String() + renderOne(q)
	}

	entries := all()
	if len(entries) == 0 {
		b.WriteString("_Nobody has checked in yet._\n\n")
		b.WriteString("> Call `CheckIn()` to start a streak.\n")
		return b.String()
	}

	// gno's sort has Sort(Interface) but no Slice(), so ranking goes through an
	// explicit sort.Interface. Ties break on address so the board is stable.
	sort.Sort(byBest(entries))
	if len(entries) > maxLeaderboard {
		entries = entries[:maxLeaderboard]
	}

	b.WriteString("| # | address | current | best | check-ins |\n|---|---|---|---|---|\n")
	for i, e := range entries {
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(" | `")
		b.WriteString(e.addr)
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(e.current))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(e.best))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(e.total))
		b.WriteString(" |\n")
	}
	return b.String()
}

// renderOne renders a single address's standing.
func renderOne(q string) string {
	addr := address(q)
	var b strings.Builder
	b.WriteString("## `")
	b.WriteString(q)
	b.WriteString("`\n\n")
	if !addr.IsValid() {
		b.WriteString("_Not a valid address._\n")
		return b.String()
	}
	r := get(addr)
	if r == nil {
		b.WriteString("_No check-ins yet._\n")
		return b.String()
	}
	b.WriteString("- current streak: **")
	b.WriteString(strconv.Itoa(Current(addr)))
	b.WriteString("**\n- best streak: **")
	b.WriteString(strconv.Itoa(r.best))
	b.WriteString("**\n- total check-ins: **")
	b.WriteString(strconv.Itoa(r.totalIn))
	b.WriteString("**\n- last check-in: day **")
	b.WriteString(strconv.FormatInt(r.lastDay, 10))
	b.WriteString("**\n")
	return b.String()
}

// all flattens the tree into a slice.
func all() []entry {
	out := []entry{}
	users.Iterate("", "", func(k string, v any) bool {
		r := v.(*record)
		out = append(out, entry{
			addr:    k,
			current: Current(address(k)),
			best:    r.best,
			total:   r.totalIn,
		})
		return false
	})
	return out
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

// Package pixelcanvas is a shared 16x16 pixel canvas: anyone can paint one
// cell at a time from a fixed 9-colour palette, and the canvas renders in
// gnoweb as a grid of coloured blocks.
//
// The canvas is a flat [Size*Size]int of palette indices held in realm state —
// a fixed-size array rather than a tree, because every cell exists from the
// start and the grid is walked in full on every render. Painting is
// last-write-wins; the realm keeps who painted each cell and a per-address
// tally, so the board doubles as a contribution leaderboard.
//
// A stateful app with nothing reusable to extract, so it ships as a lone realm
// rather than a p/ library + demo pair.
package pixelcanvas

import (
	"sort"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Size is the canvas edge length; the canvas is Size x Size cells.
const Size = 16

// palette maps a colour index to the block rendered for it. Index 0 is the
// blank canvas. Kept parallel to paletteNames.
var palette = []string{"⬜", "🟥", "🟧", "🟨", "🟩", "🟦", "🟪", "🟫", "⬛"}

// paletteNames are the names Paint accepts, in palette order.
var paletteNames = []string{"white", "red", "orange", "yellow", "green", "blue", "purple", "brown", "black"}

// Package-level persistent state.
var (
	cells    [Size * Size]int // palette index per cell, row-major
	painters [Size * Size]string
	tally    = avl.NewTree() // address string -> *int paint count
	strokes  int             // total paints ever
	lastAt   int64           // height of the most recent paint
)

// Paint colours the cell at (x, y) and returns the total number of strokes.
//
// Coordinates are 0-based with (0,0) at the top-left. Colour is a palette name
// ("red", "blue", …) — see Palette. Painting over an existing cell is allowed:
// the canvas is last-write-wins, which is the whole point of a shared board.
func Paint(cur realm, x, y int, colour string) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can paint")
	}
	if x < 0 || x >= Size || y < 0 || y >= Size {
		panic("out of bounds: x and y must be in [0," + strconv.Itoa(Size-1) + "]")
	}
	idx := colourIndex(colour)
	if idx < 0 {
		panic("unknown colour " + strconv.Quote(colour) + "; see Palette()")
	}

	addr := prev.Address()
	i := y*Size + x
	cells[i] = idx
	painters[i] = addr.String()
	strokes++
	lastAt = runtime.ChainHeight()
	bump(addr.String())

	chain.Emit("Paint",
		"addr", addr.String(),
		"x", strconv.Itoa(x),
		"y", strconv.Itoa(y),
		"colour", paletteNames[idx],
	)
	return strokes
}

// colourIndex resolves a palette name to its index, or -1.
func colourIndex(name string) int {
	n := strings.ToLower(strings.TrimSpace(name))
	for i, p := range paletteNames {
		if p == n {
			return i
		}
	}
	return -1
}

// bump increments an address's paint tally.
func bump(addr string) {
	// avl/v0's Get returns a single `any`; a miss is a nil interface.
	if v := tally.Get(addr); v != nil {
		c := v.(*int)
		*c++
		return
	}
	one := 1
	tally.Set(addr, &one)
}

// At returns the palette name of the cell at (x, y), or "" when out of bounds.
func At(x, y int) string {
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return ""
	}
	return paletteNames[cells[y*Size+x]]
}

// PainterAt returns the address that last painted (x, y), or "" if untouched.
func PainterAt(x, y int) string {
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return ""
	}
	return painters[y*Size+x]
}

// Strokes returns how many paints the canvas has taken.
func Strokes() int { return strokes }

// Palette returns the accepted colour names, comma-separated.
func Palette() string { return strings.Join(paletteNames, ", ") }

// scorer is one row of the contribution leaderboard.
type scorer struct {
	addr  string
	count int
}

// byCount ranks painters by strokes descending, ties broken on address so the
// board is deterministic.
type byCount []scorer

func (s byCount) Len() int      { return len(s) }
func (s byCount) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byCount) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].addr < s[j].addr
}

// Render renders the canvas for gnoweb.
//
//	Render("")        / Render("/") -> the canvas, palette and leaderboard
//	Render("/<x>,<y>")              -> who painted that cell, and what colour
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Pixel Canvas\n\n")
	b.WriteString("A shared ")
	b.WriteString(strconv.Itoa(Size))
	b.WriteString("x")
	b.WriteString(strconv.Itoa(Size))
	b.WriteString(" canvas. Anyone can `Paint(x, y, colour)` — last write wins.\n\n")

	if q := parseArg(path); q != "" {
		return b.String() + renderCell(q)
	}

	b.WriteString(grid())
	b.WriteString("\n**")
	b.WriteString(strconv.Itoa(strokes))
	b.WriteString("** stroke")
	if strokes != 1 {
		b.WriteString("s")
	}
	b.WriteString(" · palette: ")
	b.WriteString(Palette())
	b.WriteString("\n")

	if board := leaderboard(); board != "" {
		b.WriteString("\n## Top painters\n\n")
		b.WriteString(board)
	}
	return b.String()
}

// grid renders the canvas as rows of coloured blocks.
func grid() string {
	var b strings.Builder
	for y := 0; y < Size; y++ {
		for x := 0; x < Size; x++ {
			b.WriteString(palette[cells[y*Size+x]])
		}
		b.WriteString("\n")
	}
	return b.String()
}

// leaderboard renders the top painters, or "" when nobody has painted.
func leaderboard() string {
	scores := []scorer{}
	tally.Iterate("", "", func(k string, v any) bool {
		scores = append(scores, scorer{addr: k, count: *(v.(*int))})
		return false
	})
	if len(scores) == 0 {
		return ""
	}
	sort.Sort(byCount(scores))
	if len(scores) > 5 {
		scores = scores[:5]
	}

	var b strings.Builder
	b.WriteString("| # | address | strokes |\n|---|---|---|\n")
	for i, s := range scores {
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(" | `")
		b.WriteString(s.addr)
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(s.count))
		b.WriteString(" |\n")
	}
	return b.String()
}

// renderCell renders a single "x,y" lookup.
func renderCell(q string) string {
	var b strings.Builder
	x, y, ok := parseCoord(q)
	if !ok {
		b.WriteString("_Expected `x,y` — e.g. `/3,7`._\n")
		return b.String()
	}
	b.WriteString("## Cell (")
	b.WriteString(strconv.Itoa(x))
	b.WriteString(", ")
	b.WriteString(strconv.Itoa(y))
	b.WriteString(")\n\n")
	b.WriteString(palette[cells[y*Size+x]])
	b.WriteString(" **")
	b.WriteString(At(x, y))
	b.WriteString("**\n\n")
	if p := PainterAt(x, y); p != "" {
		b.WriteString("Painted by `")
		b.WriteString(p)
		b.WriteString("`.\n")
	} else {
		b.WriteString("_Never painted._\n")
	}
	return b.String()
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

// parseCoord parses "x,y" and reports whether it is in bounds.
func parseCoord(s string) (int, int, bool) {
	i := strings.IndexByte(s, ',')
	if i < 0 {
		return 0, 0, false
	}
	x, err := strconv.Atoi(strings.TrimSpace(s[:i]))
	if err != nil {
		return 0, 0, false
	}
	y, err2 := strconv.Atoi(strings.TrimSpace(s[i+1:]))
	if err2 != nil {
		return 0, 0, false
	}
	if x < 0 || x >= Size || y < 0 || y >= Size {
		return 0, 0, false
	}
	return x, y, true
}

